/** A scalar value allowed inside a matrix combination. */
export type MatrixValue = string | number | boolean;

/** A single fully-resolved combination, e.g. { os: "ubuntu-latest", language: "20" }. */
export type Combination = Record<string, MatrixValue>;

/** The matrix sub-block of a GitHub Actions strategy. */
export interface StrategyMatrix {
  [axis: string]: MatrixValue[] | Combination[] | undefined;
  include?: Combination[];
  exclude?: Combination[];
}

/** A GitHub Actions `jobs.<id>.strategy` object. */
export interface Strategy {
  "fail-fast": boolean;
  "max-parallel"?: number;
  matrix: StrategyMatrix;
}

/** Result of expanding a matrix configuration. */
export interface MatrixResult {
  /** GitHub-Actions-ready strategy block (drop straight into a workflow). */
  strategy: Strategy;
  /** Fully expanded list of build combinations (after exclude/include rules). */
  combinations: Combination[];
  /** Number of combinations (== combinations.length). */
  count: number;
}

/**
 * Thrown when the expanded matrix has more combinations than `maxSize` allows.
 * Carries the offending sizes so callers can render a meaningful message.
 */
export class MatrixSizeError extends Error {
  constructor(
    public readonly actual: number,
    public readonly maxSize: number,
  ) {
    super(
      `Matrix has ${actual} combinations, which exceeds the maximum of ${maxSize}. ` +
        `Reduce the number of axis values, add exclude rules, or raise maxSize.`,
    );
    this.name = "MatrixSizeError";
  }
}

/** Declarative matrix configuration (the input to {@link generateMatrix}). */
export interface MatrixConfig {
  /** Operating system axis. */
  os?: MatrixValue[];
  /** Language / runtime version axis. */
  language?: MatrixValue[];
  /** Feature-flag axis. */
  features?: MatrixValue[];
  /** Combinations to remove (partial match against expanded combinations). */
  exclude?: Combination[];
  /** Combinations to add/extend (GitHub Actions `matrix.include` semantics). */
  include?: Combination[];
  /** Limit on concurrently-running jobs (GitHub `strategy.max-parallel`). */
  maxParallel?: number;
  /** Whether to cancel in-progress jobs if any matrix job fails (default true). */
  failFast?: boolean;
  /** Hard cap on the number of expanded combinations (default 256, GitHub's limit). */
  maxSize?: number;
}

/** GitHub Actions itself caps a matrix at 256 combinations. */
export const DEFAULT_MAX_SIZE = 256;

/**
 * Return true if `combo` matches `pattern`: every key in `pattern` is present
 * in `combo` with an equal value. Extra keys in `combo` are ignored, so a
 * partial pattern (e.g. just `{ os }`) matches many combinations.
 */
function matchesPattern(combo: Combination, pattern: Combination): boolean {
  return Object.keys(pattern).every((key) => combo[key] === pattern[key]);
}

/** Remove every combination matching any exclude entry. */
function applyExclude(combinations: Combination[], excludes: Combination[]): Combination[] {
  if (excludes.length === 0) return combinations;
  return combinations.filter(
    (combo) => !excludes.some((pattern) => matchesPattern(combo, pattern)),
  );
}

/**
 * Compute the cartesian product of a set of named axes, preserving the order
 * in which axes are declared and the order of values within each axis. This
 * matches GitHub Actions' expansion order (first axis varies slowest).
 */
function cartesianProduct(axes: Record<string, MatrixValue[]>): Combination[] {
  const keys = Object.keys(axes);
  // Seed with a single empty combination so that an empty axis set yields [].
  let combinations: Combination[] = [{}];
  for (const key of keys) {
    const values = axes[key];
    const next: Combination[] = [];
    for (const combo of combinations) {
      for (const value of values) {
        next.push({ ...combo, [key]: value });
      }
    }
    combinations = next;
  }
  return combinations;
}

/**
 * Collect the declared named axes (os/language/features) into an ordered
 * axis map, skipping any axis that is absent or empty.
 */
function collectAxes(config: MatrixConfig): Record<string, MatrixValue[]> {
  const axes: Record<string, MatrixValue[]> = {};
  for (const key of ["os", "language", "features"] as const) {
    const values = config[key];
    if (values && values.length > 0) {
      axes[key] = values;
    }
  }
  return axes;
}

/**
 * Apply GitHub Actions `include` semantics.
 *
 * For each include entry, in order:
 *  - It can extend an expanded combination only if it does NOT overwrite any
 *    of that combination's ORIGINAL axis values (non-axis keys may differ).
 *  - It is added to every combination it can extend.
 *  - If it cannot extend ANY combination, it is appended as a brand-new
 *    standalone combination.
 *
 * Only the original cartesian-product combinations are eligible for
 * extension; combinations created by earlier include entries are not.
 */
function applyInclude(
  combinations: Combination[],
  includes: Combination[],
  axisKeys: string[],
): Combination[] {
  if (includes.length === 0) return combinations;

  const axisKeySet = new Set(axisKeys);
  // Mark which entries come from the original expansion (extendable).
  const result: Combination[] = combinations.map((c) => ({ ...c }));
  const originalCount = result.length;

  for (const include of includes) {
    let matched = false;
    for (let i = 0; i < originalCount; i++) {
      const combo = result[i];
      // The include overwrites an original axis value if it sets an axis key
      // to a value different from the combination's current value.
      const overwritesAxis = Object.keys(include).some(
        (key) => axisKeySet.has(key) && combo[key] !== include[key],
      );
      if (overwritesAxis) continue;
      // Eligible: merge the include's keys in (added values may be overwritten).
      result[i] = { ...combo, ...include };
      matched = true;
    }
    if (!matched) {
      // Could not extend any combination -> standalone new combination.
      result.push({ ...include });
    }
  }
  return result;
}

/** Generate the expanded build matrix from a configuration. */
export function generateMatrix(config: MatrixConfig): MatrixResult {
  const axes = collectAxes(config);
  const axisKeys = Object.keys(axes);
  let combinations = cartesianProduct(axes);
  combinations = applyExclude(combinations, config.exclude ?? []);
  combinations = applyInclude(combinations, config.include ?? [], axisKeys);
  return { combinations, count: combinations.length };
}

// TDD: RED step #1.
// The very first behaviour we need is expanding the named matrix axes
// (os / language / features) into the full cartesian product of
// combinations, exactly as GitHub Actions does for strategy.matrix.
//
// We import from a module that does not exist yet, so this test fails to
// even compile/import -> RED. We then write the minimum code to go GREEN.
import { test, expect } from "bun:test";
import { generateMatrix, MatrixSizeError } from "./matrix-generator";

test("expands named axes into the full cartesian product", () => {
  const result = generateMatrix({
    os: ["ubuntu-latest", "windows-latest"],
    language: ["18", "20"],
  });

  // 2 OS * 2 language versions = 4 combinations
  expect(result.count).toBe(4);
  expect(result.combinations).toEqual([
    { os: "ubuntu-latest", language: "18" },
    { os: "ubuntu-latest", language: "20" },
    { os: "windows-latest", language: "18" },
    { os: "windows-latest", language: "20" },
  ]);
});

// TDD: RED step #2 — exclude rules.
// An exclude entry removes every combination that matches ALL of its
// key:value pairs (a partial match against the combination), mirroring
// GitHub Actions' `matrix.exclude` semantics.
test("exclude removes combinations matching all of an exclude entry's pairs", () => {
  const result = generateMatrix({
    os: ["ubuntu-latest", "windows-latest"],
    language: ["18", "20"],
    exclude: [{ os: "windows-latest", language: "18" }],
  });

  expect(result.count).toBe(3);
  expect(result.combinations).toEqual([
    { os: "ubuntu-latest", language: "18" },
    { os: "ubuntu-latest", language: "20" },
    { os: "windows-latest", language: "20" },
  ]);
});

test("a partial exclude entry removes every matching combination", () => {
  const result = generateMatrix({
    os: ["ubuntu-latest", "windows-latest"],
    language: ["18", "20"],
    // Only `os` specified -> removes BOTH windows combinations.
    exclude: [{ os: "windows-latest" }],
  });

  expect(result.count).toBe(2);
  expect(result.combinations).toEqual([
    { os: "ubuntu-latest", language: "18" },
    { os: "ubuntu-latest", language: "20" },
  ]);
});

// TDD: RED step #3 — include rules (GitHub Actions semantics).
//
// For each include object: add its key:value pairs to every existing
// combination that does NOT overwrite an original matrix axis value. If it
// cannot be added to ANY combination, append it as a brand-new combination.
test("include extends matching combinations with extra keys", () => {
  const result = generateMatrix({
    os: ["ubuntu-latest", "windows-latest"],
    language: ["18", "20"],
    // Adds `experimental: true` only to the windows+20 combination.
    include: [{ os: "windows-latest", language: "20", experimental: true }],
  });

  expect(result.count).toBe(4);
  expect(result.combinations).toEqual([
    { os: "ubuntu-latest", language: "18" },
    { os: "ubuntu-latest", language: "20" },
    { os: "windows-latest", language: "18" },
    { os: "windows-latest", language: "20", experimental: true },
  ]);
});

test("include adds an extra key to multiple matching combinations", () => {
  const result = generateMatrix({
    os: ["ubuntu-latest", "windows-latest"],
    language: ["18", "20"],
    // Matches both language:18 combinations (partial match on language).
    include: [{ language: "18", lts: true }],
  });

  expect(result.combinations).toEqual([
    { os: "ubuntu-latest", language: "18", lts: true },
    { os: "ubuntu-latest", language: "20" },
    { os: "windows-latest", language: "18", lts: true },
    { os: "windows-latest", language: "20" },
  ]);
});

test("include that overwrites an original axis value becomes a new combination", () => {
  const result = generateMatrix({
    os: ["ubuntu-latest"],
    language: ["18", "20"],
    // os:macos-latest is not an original axis value here, so this entry
    // cannot extend any existing combination -> appended as new.
    include: [{ os: "macos-latest", language: "22" }],
  });

  expect(result.count).toBe(3);
  expect(result.combinations).toEqual([
    { os: "ubuntu-latest", language: "18" },
    { os: "ubuntu-latest", language: "20" },
    { os: "macos-latest", language: "22" },
  ]);
});

test("include with only new keys is added to every combination", () => {
  const result = generateMatrix({
    os: ["ubuntu-latest", "windows-latest"],
    // No keys overlap with any axis -> added to all combinations.
    include: [{ color: "green" }],
  });

  expect(result.combinations).toEqual([
    { os: "ubuntu-latest", color: "green" },
    { os: "windows-latest", color: "green" },
  ]);
});

// TDD: RED step #4 — third axis (features) participates in the product.
test("features axis participates in the cartesian product", () => {
  const result = generateMatrix({
    os: ["ubuntu-latest"],
    language: ["20"],
    features: ["minimal", "full"],
  });

  expect(result.count).toBe(2);
  expect(result.combinations).toEqual([
    { os: "ubuntu-latest", language: "20", features: "minimal" },
    { os: "ubuntu-latest", language: "20", features: "full" },
  ]);
});

// TDD: RED step #5 — the GitHub-Actions-ready strategy block.
test("builds a strategy block with fail-fast, max-parallel and matrix", () => {
  const result = generateMatrix({
    os: ["ubuntu-latest", "windows-latest"],
    language: ["20"],
    failFast: false,
    maxParallel: 2,
  });

  expect(result.strategy["fail-fast"]).toBe(false);
  expect(result.strategy["max-parallel"]).toBe(2);
  expect(result.strategy.matrix.os).toEqual(["ubuntu-latest", "windows-latest"]);
  expect(result.strategy.matrix.language).toEqual(["20"]);
});

test("fail-fast defaults to true and max-parallel is omitted when unset", () => {
  const result = generateMatrix({ os: ["ubuntu-latest"] });
  expect(result.strategy["fail-fast"]).toBe(true);
  expect(result.strategy).not.toHaveProperty("max-parallel");
});

test("strategy.matrix carries include and exclude through to output", () => {
  const result = generateMatrix({
    os: ["ubuntu-latest"],
    language: ["18", "20"],
    include: [{ os: "macos-latest", language: "22" }],
    exclude: [{ language: "18" }],
  });
  expect(result.strategy.matrix.include).toEqual([{ os: "macos-latest", language: "22" }]);
  expect(result.strategy.matrix.exclude).toEqual([{ language: "18" }]);
});

// TDD: RED step #6 — max-size validation.
test("throws MatrixSizeError when the matrix exceeds maxSize", () => {
  expect(() =>
    generateMatrix({
      os: ["a", "b", "c"],
      language: ["1", "2", "3"],
      maxSize: 5, // 3*3 = 9 > 5
    }),
  ).toThrow(MatrixSizeError);
});

test("MatrixSizeError reports the actual and maximum sizes", () => {
  let caught: MatrixSizeError | undefined;
  try {
    generateMatrix({ os: ["a", "b", "c"], language: ["1", "2", "3"], maxSize: 5 });
  } catch (e) {
    caught = e as MatrixSizeError;
  }
  expect(caught).toBeInstanceOf(MatrixSizeError);
  expect(caught!.actual).toBe(9);
  expect(caught!.maxSize).toBe(5);
  expect(caught!.message).toContain("9");
  expect(caught!.message).toContain("5");
});

test("does not throw when matrix is exactly at maxSize", () => {
  expect(() => generateMatrix({ os: ["a", "b"], language: ["1", "2"], maxSize: 4 })).not.toThrow();
});

